      activeIndex: 10,
      activePayload: { test: 'data' },
      activeLabel: 'test-label',
      isHovering: false,
    })
  })

  it('should handle undefined syncId', () => {
    const { result } = renderHook(() => useChartSync(undefined))

    act(() => {
