const CHART_HOVER_SYNC_STORAGE_KEY = 'supabase-chart-hover-sync-enabled'
const CHART_TOOLTIP_SYNC_STORAGE_KEY = 'supabase-chart-tooltip-sync-enabled'

// Minimal safe wrapper around localStorage. Guards against SSR / unavailable
// storage and swallows write errors (e.g. quota exceeded) so a failed persist
// never breaks the in-memory hover state.
const safeStorage = {
  getItem(key: string): string | null {
    try {
      if (typeof window === 'undefined') return null
      return window.localStorage.getItem(key)
    } catch {
      return null
    }
  },
  setItem(key: string, value: string): void {
    try {
      if (typeof window === 'undefined') return
      window.localStorage.setItem(key, value)
    } catch (error) {
      console.warn('Failed to save chart hover sync setting to localStorage:', error)
    }
  },
}

// Global state shared across all hook instances
let globalState: ChartHoverState = {
  hoveredIndex: null,
  hoveredChart: null,
  syncHover: true,
  syncTooltip: true,
}

// Subscribers for state changes
const subscribers = new Set<(state: ChartHoverState) => void>()

// Load initial sync settings from localStorage. The try/catch guards JSON.parse
// against corrupted / non-parseable values, in which case we keep the defaults.
try {
  const hoverSyncStored = safeStorage.getItem(CHART_HOVER_SYNC_STORAGE_KEY)
  const tooltipSyncStored = safeStorage.getItem(CHART_TOOLTIP_SYNC_STORAGE_KEY)

  if (hoverSyncStored !== null) {
    globalState.syncHover = JSON.parse(hoverSyncStored)
  }
  if (tooltipSyncStored !== null) {
    globalState.syncTooltip = JSON.parse(tooltipSyncStored)
  }
